local _EVENTS = {
    START_UPDATE = "start_update", --开始更新
    RESET_UPDATE = "reset_update", -- 重置下载
    ON_CHECK_UPDATE_FAILED = "on_check_update_failed", -- 检查本地更新状态失败
    ON_CHECK_UPDATE_SUCC = "on_check_update_succ", -- 检查本地更新状态成功
    ON_UPDATE_CONFIRMED = "on_update_confirmed", -- 资源确定更新
