    ON_DOWNLOAD_COMPLETE = "on_download_complete", -- 资源下载完成
    ON_DOWNLOAD_COMPLETE_APPLY = "on_download_complete_apply", -- 开始应用资源
    ON_DOWNLOAD_FAILED = "on_download_failed", -- 资源下载失败
    ON_APPLY_FAILED = "on_apply_failed", -- 资源应用失败
